// Checks the built site for the SEO and GEO guarantees in docs/specs/001_static-posts.md.
// Pages are generated by our own build, so plain pattern matching is enough here.
import { existsSync, readdirSync, readFileSync, statSync } from 'node:fs';
import { join, relative, sep } from 'node:path';
import { pathToFileURL } from 'node:url';

const walk = (dir) =>
  readdirSync(dir).flatMap((name) => {
    const path = join(dir, name);
    return statSync(path).isDirectory() ? walk(path) : [path];
  });

const tags = (html, name) => html.match(new RegExp(`<${name}\\b[^>]*>`, 'g')) ?? [];
const attr = (tag, name) => tag.match(new RegExp(`\\s${name}=(?:"([^"]*)"|'([^']*)')`))?.slice(1).find((v) => v !== undefined);
const metaContent = (html, name) => {
  const tag = tags(html, 'meta').find((t) => attr(t, 'name') === name);
  return tag && attr(tag, 'content');
};
const urlOf = (file, dist, site) => {
  const path = relative(dist, file).split(sep).join('/').replace(/index\.html$/, '');
  return new URL(`/${path}`, site).href;
};
const fileOf = (url, dist) => join(dist, new URL(url).pathname, 'index.html');
const read = (path) => (existsSync(path) ? readFileSync(path, 'utf8') : '');

const jsonLdBlocks = (html) =>
  [...html.matchAll(/<script\b[^>]*type="application\/ld\+json"[^>]*>([\s\S]*?)<\/script>/g)].map((m) => m[1]);

const sitemapUrls = (dist) => {
  const locs = (xml) => [...xml.matchAll(/<loc>([^<]+)<\/loc>/g)].map((m) => m[1]);
  return locs(read(join(dist, 'sitemap-index.xml'))).flatMap((child) =>
    locs(read(join(dist, new URL(child).pathname))),
  );
};

const draftSlugs = (postsDir) =>
  existsSync(postsDir)
    ? readdirSync(postsDir)
        .filter((f) => f.endsWith('.md') && /^draft:\s*true\s*$/m.test(readFileSync(join(postsDir, f), 'utf8')))
        .map((f) => f.replace(/\.md$/, ''))
    : [];

export function checkSite({ dist, postsDir, site }) {
  const errors = [];
  const fail = (rule, where, message) => errors.push({ rule, where, message });

  const htmlFiles = walk(dist).filter((f) => f.endsWith('.html'));
  const pages = htmlFiles.map((file) => ({ file, url: urlOf(file, dist, site), html: read(file) }));
  const isNoindex = (html) => /noindex/.test(metaContent(html, 'robots') ?? '');
  const indexable = pages.filter((p) => !isNoindex(p.html));
  const seen = { title: new Map(), description: new Map() };

  for (const { file, url, html } of indexable) {
    const where = relative(dist, file);

    // Rule 1: one h1, title, description, self-referencing canonical.
    const h1s = tags(html, 'h1').length;
    if (h1s !== 1) fail(1, where, `expected one h1, found ${h1s}`);
    const title = html.match(/<title>([^<]*)<\/title>/)?.[1];
    if (!title) fail(1, where, 'missing title');
    const description = metaContent(html, 'description');
    if (!description) fail(1, where, 'missing meta description');
    const canonical = tags(html, 'link').find((t) => attr(t, 'rel') === 'canonical');
    if (!canonical || attr(canonical, 'href') !== url) {
      fail(1, where, `canonical ${canonical ? attr(canonical, 'href') : 'missing'} is not ${url}`);
    }

    // Rule 2: unique titles and descriptions.
    for (const [kind, value] of [['title', title], ['description', description]]) {
      if (!value) continue;
      if (seen[kind].has(value)) fail(2, where, `${kind} duplicates ${seen[kind].get(value)}`);
      else seen[kind].set(value, where);
    }

    // Rule 3: JSON-LD parses, and post pages tie their author to the Person.
    const blocks = [];
    for (const block of jsonLdBlocks(html)) {
      try {
        blocks.push(JSON.parse(block));
      } catch {
        fail(3, where, 'JSON-LD does not parse');
      }
    }
    if (/\/writing\/[^/]+\/$/.test(url)) {
      const ofType = (type) => blocks.find((b) => b['@type'] === type);
      if (!ofType('BlogPosting')) fail(3, where, 'missing BlogPosting');
      if (!ofType('BreadcrumbList')) fail(3, where, 'missing BreadcrumbList');
      const authorId = ofType('BlogPosting')?.author?.['@id'];
      if (ofType('BlogPosting') && (!authorId || authorId !== ofType('Person')?.['@id'])) {
        fail(3, where, `BlogPosting author ${authorId} does not match Person @id`);
      }
    }

    // Rule 7: every image has alt text attribute.
    for (const img of tags(html, 'img')) {
      if (attr(img, 'alt') === undefined) fail(7, where, `img without alt: ${img}`);
    }
  }

  // Rule 4: the sitemap and the indexable pages match exactly.
  const listed = new Set(sitemapUrls(dist));
  for (const { url, file } of indexable) {
    if (!listed.has(url)) fail(4, relative(dist, file), `${url} is not in the sitemap`);
  }
  for (const url of listed) {
    const html = read(fileOf(url, dist));
    if (!html) fail(4, 'sitemap', `${url} has no matching file`);
    else if (isNoindex(html)) fail(4, 'sitemap', `${url} is noindex`);
  }

  // Rule 5: every post has its image and twin, and is in both feeds.
  const rss = read(join(dist, 'rss.xml'));
  const llms = read(join(dist, 'llms.txt'));
  const postPages = pages.filter((p) => /\/writing\/[^/]+\/$/.test(p.url));
  for (const { url } of postPages) {
    const slug = new URL(url).pathname.split('/')[2];
    if (!existsSync(join(dist, 'writing', slug, 'og.png'))) fail(5, slug, 'missing og.png');
    if (!existsSync(join(dist, 'writing', `${slug}.md`))) fail(5, slug, 'missing Markdown twin');
    if (!rss.includes(url)) fail(5, slug, 'missing from rss.xml');
    if (!llms.includes(url)) fail(5, slug, 'missing from llms.txt');
  }

  // Rule 6: drafts leave no trace in any output.
  const textFiles = walk(dist).filter((f) => /\.(html|xml|txt|md)$/.test(f));
  for (const slug of draftSlugs(postsDir)) {
    for (const file of textFiles) {
      if (read(file).includes(`/writing/${slug}`)) fail(6, relative(dist, file), `references draft ${slug}`);
    }
    if (existsSync(join(dist, 'writing', slug))) fail(6, `writing/${slug}`, 'draft was built');
  }

  return errors;
}

if (import.meta.url === pathToFileURL(process.argv[1]).href) {
  const errors = checkSite({ dist: 'dist', postsDir: 'src/content/posts', site: 'https://rafagomes.tech' });
  for (const { rule, where, message } of errors) console.error(`rule ${rule}: ${where}: ${message}`);
  if (errors.length) process.exit(1);
  console.log('check-site: all rules passed');
}
